st.set_page_config(page_title="Cartografia · Repàs per al 10", page_icon="🗺️", layout="centered")

QUESTIONS = [('Què és la cartografia?', ["L'estudi i elaboració de mapes geogràfics", 'Només el dibuix artístic de paisatges', 'La ciència que estudia únicament els oceans', 'Un sistema per mesurar el temps'], 0, 'La cartografia estudia i elabora representacions de la superfície terrestre en dues dimensions.'), ('Quin objectiu té el llenguatge cartogràfic?', ['Substituir totes les dades per fotografies', 'Comunicar informació espacial entre qui produeix i qui utilitza mapes', 'Representar tots els detalls sense simplificar', "Evitar l'ús de símbols"], 1, 'El mapa és un mitjà de comunicació amb un missatge específic.'), ("Quin d'aquests NO és un procés característic del llenguatge cartogràfic?", ['Projecció', 'Escala', 'Simbolització', 'Gravació de so'], 3, 'El llenguatge cartogràfic utilitza projeccions, escala, simbolització i generalització.'), ('Què és un plànol?', ["Document de gran escala d'una zona poc extensa o d'una obra", 'Representació global de tota la Terra', 'Sempre una fotografia aèria', 'Un mapa temàtic de clima exclusivament'], 0, 'El plànol representa àrees reduïdes amb molt detall i normalment no necessita projecció.'), ('Quina característica correspon a un mapa?', ['No considera mai la curvatura terrestre', 'Representa sempre una sola edificació', 'Representa un territori relativament extens i considera la curvatura terrestre', 'Només es fa a mà'], 2, 'Els mapes cobreixen àrees més grans i requereixen projecció cartogràfica.'), ('Què és un croquis?', ["Un model digital d'elevacions", 'Una representació esquemàtica, poc detallada i sovint feta a mà', 'Un mapa oficial amb coordenades UTM obligatòries', 'Una fotografia rectificada'], 1, 'El croquis plasma informació ràpidament, amb poca precisió i detall.'), ('Què és un ortofotomapa?', ['Un mapa només de carreteres', 'Una carta de navegació marítima', 'Una representació basada en fotografies aèries o de satèl·lit rectificades i ajustades a una xarxa geodèsica', 'Un plànol sense escala'], 2, 'Les fotografies es rectifiquen per tenir una escala uniforme i ajustar-se a una xarxa geodèsica.'), ('Què va publicar Abraham Ortelius el 1570?', ['El primer GPS', 'La primera col·lecció de mapes moderns i manejables', 'El sistema UTM', 'El primer SIG digital'], 1, 'És una fita històrica destacada als apunts.'), ("A qui s'associa la projecció del mapamundi de 1569?", ['Claudi Ptolemeu', 'Abraham Ortelius', 'Gerardus Mercator', 'Bosque'], 2, 'Mercator va publicar el seu mapamundi el 1569.'), ('Què descriu millor un mapa topogràfic?', ['Un tema únic com la renda', 'Elements naturals i artificials i les seves relacions espacials', 'Només els límits administratius', 'Només fotografies sense símbols'], 1, 'Inclou muntanyes, valls, aigües, ciutats, carreteres i altres elements.'), ('Què és un mapa temàtic?', ['Un mapa centrat en un tema concret sobre una base cartogràfica', 'Un mapa sense llegenda', "Un plànol d'arquitectura exclusivament", 'Un mapa que no representa variables'], 0, 'Pot representar variables socials, econòmiques, ambientals o físiques.'), ('Quina diferència clau hi ha entre mapa analògic i digital?', ['El digital no pot contenir dades', "L'analògic sempre és més precís", 'El digital emmagatzema informació en fitxers o bases de dades i facilita actualitzar-la i visualitzar-la en suports diferents', "L'analògic utilitza capes activables"], 2, "En el mapa analògic geometria i simbolització són inseparables; en el digital la informació s'emmagatzema separadament."), ('Què estudia la toponímia?', ["L'origen dels noms propis de lloc", 'La forma del geoide', 'La inclinació del terreny', 'Els colors de les llegendes'], 0, "La toponímia és una branca de l'onomàstica que estudia els noms de lloc."), ('Què és un topònim?', ['Un símbol de nord', 'El nom propi amb què es designa una entitat topogràfica', 'Una escala gràfica', 'Un tipus de projecció'], 1, "També s'anomena nom geogràfic."), ('En el topònim «riu Llobregat», quin és el terme genèric?', ['Llobregat', 'Riu', 'Tots dos són específics', 'No hi ha terme genèric'], 1, "«Riu» identifica la naturalesa general de l'entitat geogràfica."), ("Què és el terme específic d'un topònim?", ["La part que identifica particularment l'entitat", 'La categoria general, com riu o pic', 'Una nota a peu de mapa', 'El sistema de coordenades'], 0, "El terme específic diferencia l'entitat concreta, per exemple Llobregat."), ('Què és un topònim oficial?', ['Un nom inventat per qualsevol usuari', 'Un nom geogràfic establert per una autoritat competent i publicat oficialment', "Un nom traduït sempre a l'anglès", 'Un nom antic sense ús'], 1, 'La definició implica autoritat competent, procediment administratiu i publicació oficial.'), ('Què és un endònim?', ['Un topònim en la llengua pròpia del lloc o una llengua oficial del territori', 'Una adaptació tradicional del nom en una llengua externa', "Un nom descriptiu d'un edifici", 'Un nom sense ubicació'], 0, "L'exemple dels apunts contraposa London (endònim) i Londres (exònim)."), ('Què és un exònim?', ['El nom oficial en totes les llengües', "Una adaptació tradicional d'un nom geogràfic fora del territori on es parla aquella llengua", "El terme genèric d'un topònim", 'Un catàleg de noms'], 1, 'Els apunts donen Londres, Nàpols, Nova York i Pequín com a exemples.'), ('Què conté un nomenclàtor?', ['Només imatges de satèl·lit', "Un catàleg de topònims amb informació descriptiva i d'ubicació", 'Només escales gràfiques', 'Dades meteorològiques horàries'], 1, "Pot incloure ubicació, tipus d'accident geogràfic i hidrografia."), ('Quin organisme gestiona el Nomenclàtor oficial de toponímia major de Catalunya segons els apunts?', ['CREAF', 'UAB exclusivament', 'ICGC', 'NASA'], 2, "Els apunts indiquen que el gestiona l'Institut Cartogràfic i Geològic de Catalunya."), ("Quin element bàsic d'un mapa explica el significat dels símbols?", ['El títol', 'La llegenda', "L'any de referència", "L'autor"], 1, 'La llegenda facilita interpretar colors, icones i símbols.'), ("Quin conjunt inclou elements bàsics d'un mapa?", ['Títol, llegenda, escala, orientació i font', 'Només colors i fotografies', 'Només coordenades i autor', 'Únicament el nord'], 0, 'També pot incloure subtítol, mapa base, any, metadades i logos.'), ("Com es defineix l'escala d'un mapa?", ['Distància real dividida per latitud', 'Proporció entre la dimensió al mapa i la dimensió real', 'Nombre de símbols per quilòmetre', 'Angle entre dos nords'], 1, 'Escala = dimensió al mapa / dimensió real.'), ('Quina escala representa més detall?', ['1:1.000.000', '1:500.000', '1:5.000', '1:100.000'], 2, 'Una escala gran té denominador petit i representa més detall.'), ('Quina escala és més petita?', ['1:1.000', '1:5.000', '1:25.000', '1:1.000.000'], 3, "Com més gran és el denominador, més petita és l'escala i més general la representació."), ('A escala 1:50.000, quina distància real representa 1 cm al mapa?', ['50 m', '500 m', '5 km', '50 km'], 1, '1 cm × 50.000 = 50.000 cm = 500 m.'), ('A escala 1:250.000, 1 cm al mapa equival a…', ['250 m', '2,5 km', '25 km', '250 km'], 1, '250.000 cm són 2.500 m, és a dir, 2,5 km.'), ('A escala 1:1.000.000, 1 cm al mapa equival a…', ['100 m', '1 km', '10 km', '100 km'], 2, '1.000.000 cm són 10 km.'), ('A escala 1:25.000, 1 cm representa quants metres reals?', ['25 m', '250 m', '2.500 m', '25 km'], 1, '25.000 cm = 250 m.'), ('Què és la simbologia cartogràfica?', ["L'ús de signes com nord, escala i símbols geològics o d'infraestructures", "El text de l'examen", 'El sistema de datum', 'La forma del geoide'], 0, 'Els símbols ajuden a comunicar i interpretar els elements representats.'), ('Quins són els tres nords que distingeixen els apunts?', ['Nord local, nord solar i nord lunar', 'Nord magnètic, geogràfic i de projecció/quadrícula', 'Nord UTM, nord GPS i nord equatorial', 'Nord real, nord fals i nord vertical'], 1, 'Són NM, NG i NP/NQ.'), ('Què indica el nord magnètic?', ["L'eix vertical de la quadrícula", 'El punt on convergeixen tots els meridians', "La direcció assenyalada per l'agulla imantada de la brúixola", 'Sempre el mateix punt que el nord geogràfic'], 2, 'La brúixola assenyala el nord magnètic.'), ("Com s'anomena l'angle entre el nord geogràfic i el nord magnètic?", ['Equidistància', 'Declinació magnètica', 'Convergència de quadrícula', 'Azimut'], 1, 'La declinació és la diferència angular entre NG i NM.'), ("Com s'anomena la diferència angular entre nord de projecció i nord geogràfic?", ['Declinació', 'Rumb', 'Convergència de quadrícula', 'Equidistància'], 2, 'Així ho defineixen els apunts.'), ("Com es mesura l'azimut segons els apunts?", ['Des del sud en sentit antihorari', 'Des del nord geogràfic en sentit horari', "Des de l'est en sentit horari", 'Sempre des del nord magnètic'], 1, "L'azimut cap a l'est és 90° i cap a l'oest 270°."), ("Quin azimut correspon a una direcció cap a l'est?", ['0°', '90°', '180°', '270°'], 1, "L'azimut es compta en sentit horari des del nord geogràfic."), ('Què vol dir SIG?', ['Sistema Internacional Geomètric', "Sistema d'Informació Geogràfica", "Servei d'Imatges Globals", "Sistema d'Indicadors Geològics"], 1, 'En anglès és GIS: Geographic Information System.'), ('Quina activitat pot fer un SIG?', ['Només imprimir mapes en paper', 'Gestionar, manipular, analitzar, modelar i representar dades georeferenciades', 'Només dibuixar logotips', 'Únicament mesurar temperatura'], 1, 'Aquesta és la definició recollida als apunts.'), ('Què significa georeferenciar informació?', ["Assignar-la a una ubicació geogràfica dins d'un sistema de referència", 'Canviar tots els topònims', 'Convertir-la en una fotografia', 'Eliminar les coordenades'], 0, "Els elements han d'estar localitzats en un lloc geogràfic."), ('Per què serveix la superposició de capes en un SIG?', ['Perquè totes les capes tinguin colors idèntics', 'Per separar la informació temàtica i activar o desactivar capes', 'Per eliminar les bases de dades', 'Per evitar utilitzar sistemes de referència'], 1, 'Les capes poden representar usos del sòl, vegetació, carreteres, geologia, etc.'), ("Quin programa s'identifica als apunts com a exemple de CAD?", ['QGIS', 'AutoCAD', 'Google Earth', 'SIGNA'], 1, "CAD significa Disseny Assistit per Ordinador; AutoCAD s'utilitza en dibuix 2D/3D."), ("Quina és una funció habitual d'un programari cartogràfic?", ['Accedir a formats vectorials i ràster', 'Només reproduir àudio', 'Evitar consultes de dades', 'No permetre imprimir plànols'], 0, 'Els apunts inclouen formats vectorials, ràster, serveis remots, bases de dades, selecció i impressió.'), ('Què és un MDT?', ['Una estructura numèrica de dades que representa digitalment el terreny amb diverses capes', 'Una brúixola digital', 'Un mapa exclusivament de carreteres', 'Un sistema de noms geogràfics'], 0, "Les capes del MDT deriven habitualment d'una capa d'elevacions, el MDE."), ('Què representa un MDE?', ['La distribució de topònims', "L'altitud del relleu mitjançant mostres regulars o irregulars", 'Només la vegetació', 'La densitat de població'], 1, "Els apunts ho expressen com z = f(x,y), on x i y localitzen el punt i z és l'elevació."), ("En l'expressió z = f(x,y), què representa z?", ['La longitud', 'La latitud', "L'elevació del punt", 'El datum'], 2, "x i y són les coordenades de localització i z és el valor d'elevació."), ('Què són les corbes de nivell?', ["Línies que uneixen punts d'igual cota", 'Línies que uneixen punts de la mateixa longitud', 'Límits municipals sempre', 'Línies de carreteres'], 0, 'Permeten representar el relleu tridimensional en un pla bidimensional.'), ("Què és l'equidistància entre corbes de nivell?", ['La distància horitzontal entre dos pobles', 'La diferència de cota entre corbes consecutives', "La longitud total d'una corba", "L'escala del mapa"], 1, "És la diferència d'altitud entre les corbes; sovint és constant."), ('Què és una xarxa irregular de triangles (TIN)?', ['Un mosaic de triangles creat a partir de punts propers no col·lineals amb elevació coneguda', 'Una quadrícula regular de píxels', 'Un catàleg de topònims', 'Una projecció cilíndrica'], 0, 'El TIN modela la superfície amb triangles de mida/forma irregular.'), ('Quin és un avantatge del TIN?', ['Sempre necessita menys processament que qualsevol ràster', "S'adapta bé a les irregularitats i permet bones visualitzacions 3D", 'Integra millor qualsevol dada temàtica sense dificultats', "No utilitza punts d'elevació"], 1, 'Els apunts també indiquen que pot ocupar menys espai.'), ("Quin inconvenient del TIN s'indica als apunts?", ['No pot representar relleu', 'Necessita més temps de processament i és menys eficient integrant altres dades', 'No permet visualització 3D', 'Només funciona al mar'], 1, 'Són dos inconvenients que apareixen a la taula dels apunts.'), ('Quin format és el més adequat per integrar elevacions del terreny en un SIG, segons els apunts?', ['Ràster', 'MP3', 'DOCX', 'Només paper'], 0, 'El material indica explícitament que el format ràster és el més adequat per a aquesta integració.'), ("Quin és un mètode directe de construcció d'un MDE amb sensors remots?", ['Digitalització de corbes de nivell', 'Restitució fotogramètrica', 'Radargrametria', 'Dibuix manual'], 2, 'La radargrametria emet un impuls radar i mesura el retard del senyal reflectit.'), ("Quin és un mètode directe sobre el terreny per obtenir dades d'un MDE?", ['Topografia convencional', 'Restitució fotogramètrica', 'Digitalització de corbes de nivell', 'Classificació de topònims'], 0, "També s'hi inclouen els sistemes de posicionament GPS."), ('Què permet la restitució fotogramètrica?', ['Obtenir mesures tridimensionals i informació de forma i posició a partir de fotografies', 'Mesurar directament la declinació magnètica', 'Crear topònims oficials', 'Calcular únicament la temperatura'], 0, 'És un mètode indirecte basat en fotografies aèries o imatges de satèl·lit.'), ('Què és la geodèsia?', ['La ciència que estudia la representació, forma i dimensions de la Terra, incloent-hi el camp gravitatori', "L'estudi exclusiu dels noms de lloc", 'La tècnica de pintar mapes', 'Un tipus de capa SIG'], 0, "També tracta l'orientació i la posició de la Terra a l'espai."), ('Què és el geoide, segons els apunts?', ['Una esfera perfecta', "Una superfície teòrica equipotencial del camp de gravetat que s'ajusta al nivell del mar", 'Una quadrícula de píxels', 'Un tipus de mapa temàtic'], 1, "Els apunts el descriuen com una superfície irregular que millor s'ajusta al nivell del mar."), ("Per què s'utilitza un el·lipsoide de revolució?", ['Per simplificar matemàticament la representació de la forma de la Terra', 'Per eliminar totes les deformacions cartogràfiques', 'Per representar només els oceans', 'Per definir la llegenda'], 0, "La definició matemàtica del geoide és complexa; l'el·lipsoide facilita els càlculs geodèsics."), ('Quants fusos té el sistema UTM?', ['20', '31', '60', '84'], 2, 'La Terra es divideix en 60 fusos UTM de 6° de longitud.'), ('Quina amplada longitudinal té cada fus UTM?', ['3°', '6°', '8°', '12°'], 1, "Els fusos van d'oest a est i tenen 6° de longitud."), ("Quantes bandes o zones latitudinals UTM s'indiquen als apunts?", ['10', '20', '31', '60'], 1, "Són 20 bandes de 8° de latitud, amb l'excepció de la banda X que fa 12°."), ('Quin rang de latitud cobreix el sistema UTM indicat als apunts?', ['De 90° S a 90° N', 'De 84° N a 80° S', 'Només entre 30° i 60° N', 'De 0° a 180°'], 1, 'UTM cobreix la zona compresa entre 84° N i 80° S.'), ('Quina propietat conserva la projecció UTM segons els apunts?', ["L'equivalència exacta de totes les distàncies", 'La conformitat, és a dir, els angles', 'Totes les àrees sense deformació', 'Totes les distàncies i àrees'], 1, "Els apunts assenyalen que manté la conformitat però no l'equivalència."), ("Quin fus s'utilitza oficialment per cartografiar Catalunya segons els apunts?", ['29 Nord', '30 Nord', '31 Nord', '32 Sud'], 2, 'El material indica que tota Catalunya utilitza el fus 31 Nord.'), ('Quin datum oficial actual indiquen els apunts per a UTM a Catalunya?', ['ED50 (EPSG:23031)', 'ETRS89 (EPSG:25831)', 'NAD27', 'OSGB36'], 1, 'Els apunts indiquen ETRS89, codi EPSG:25831.'), ("Què pot passar si s'utilitzen coordenades antigues ED50 sense convertir-les a ETRS89?", ['No canvia res mai', 'Poden quedar desplaçades aproximadament 200 metres', 'Es converteixen en graus', 'Desapareix la latitud'], 1, "El material adverteix d'un desplaçament d'uns 200 metres."), ('Quina és una unitat habitual de les coordenades UTM?', ['Metres', 'Graus Celsius', 'Radianes exclusivament', 'Quilograms'], 0, 'UTM utilitza valors mètrics bidimensionals X i Y.'), ('En coordenades UTM, què representa UTMx?', ["La distància nord des de l'equador", 'La coordenada est-oest (Easting)', "L'altitud", 'La banda de latitud'], 1, 'La coordenada X situa el punt en direcció est-oest; la Y en direcció nord-sud.'), ("En l'exemple 31T 432953 4623712, quina part identifica el fus?", ['31', 'T', '432953', '4623712'], 0, 'El primer element és el fus; T és la banda i després venen X i Y.'), ("En l'exemple UTM 31T 432953 4623712, què indica la lletra T?", ['El datum', 'La banda/zona latitudinal', "L'altitud", 'La precisió en metres'], 1, 'La coordenada completa inclou fus, banda i coordenades mètriques.'), ('A les nostres latituds, segons els apunts, coordenades amb 6 dígits a X i 7 a Y solen indicar…', ['Quilòmetres', 'Metres', 'Graus i minuts', 'Una escala gràfica'], 1, 'Els apunts contraposen 3/4 dígits per km i 6/7 dígits per metres.'), ("Si UTMx és inferior a 500.000 m, què indica en l'exemple dels apunts?", ["Que el punt és a l'esquerra del meridià central del fus", 'Que és al pol nord', "Que és al sud de l'equador necessàriament", 'Que el datum és ED50'], 0, 'El meridià central té valor de referència X = 500.000 m.'), ('Quin és un avantatge del sistema UTM?', ['Permet localitzar punts amb coordenades mètriques i calcular distàncies fàcilment', 'No té cap límit de latitud', 'No requereix datum', 'Conserva totes les àrees i distàncies'], 0, 'La projecció és conforme i les coordenades mètriques faciliten càlculs de distància.'), ('Què és un datum o sistema geodèsic de referència en el context dels apunts?', ['Un model/sistema que defineix la referència per posicionar coordenades sobre la Terra', 'Una llegenda de símbols', 'Una corba de nivell', "Un tipus de fitxer d'imatge"], 0, 'El sistema de referència permet que les coordenades concordin amb la cartografia.'), ('Per què cal conèixer el sistema de referència de les coordenades?', ['Perquè les mateixes coordenades poden correspondre a punts diferents en sistemes diferents', 'Per saber el color del mapa', 'Per calcular el nombre de topònims', 'Perquè el nord sempre sigui magnètic'], 0, 'Els apunts remarquen que coordenades amb datums diferents poden estar separades fins a uns 200 m.'), ('Quines són les fases generals del treball amb un MDT?', ['Generar MDE, tractar-lo per obtenir capes, visualitzar-les i analitzar-les', 'Imprimir, plastificar i arxivar', 'Crear topònims, traduir-los i publicar-los', 'Mesurar angles, fer una llegenda i eliminar capes'], 0, 'Són les fases enumerades als apunts.'), ("Quin exemple de capa derivada d'un MDE es dona als apunts?", ['Pendent', 'Nom oficial del municipi', 'Població activa', "Temperatura de l'aire obligatòriament"], 0, "També s'hi esmenten orientació i curvatura.")]

